cu={}
first={}
for l in open('shopify/orders.jsonl'):
    d=json.loads(l)
    if '__parentId' in d: continue
    c=d['customer']; a=d['shippingAddress'] or {}
    r=cu.setdefault(c['id'],{'email':c['email'],'name':(c['firstName'],c['lastName']),'addr':set(),'first':d['createdAt'],'n':0})
    r['addr'].add((a.get('address1'),a.get('zip'))); r['n']+=1
    r['first']=min(r['first'],d['createdAt'])
def ne(e):
    u,d=e.lower().strip().split('@'); u=u.split('+')[0]
    if d in('gmail.com','googlemail.com'): u=u.replace('.','')
    return u+'@'+d
g=C.defaultdict(list)
for k,v in cu.items(): g[ne(v['email'])].append(k)
import random
ms=[v for v in g.values() if len(v)>1]
for v in ms[:12]:
    for k in v: print(k[-8:],cu[k]['email'],cu[k]['name'],sorted(cu[k]['addr'])[:1],cu[k]['first'][:10],cu[k]['n'])
    print()
same=0
for v in ms:
    if len({cu[k]['name'] for k in v})>1: same+=1
print('groups w/ different names',same)
# name+addr groups
g2=C.defaultdict(set)
for k,v in cu.items():
    for a in v['addr']: g2[(v['name'],a)].add(k)
m2=[v for v in g2.values() if len(v)>1]
print('name+addr groups',len(m2))
inn={k for v in ms for k in v}
print('name+addr groups not covered by email rule',sum(1 for v in m2 if not v<=inn or not any(set(v)<=set(x) for x in ms)))
for v in [v for v in m2 if not any(set(v)<=set(x) for x in ms)][:8]:
    for k in v: print(k[-8:],cu[k]['email'],cu[k]['name'],sorted(cu[k]['addr'])[:2])
    print()
